import{_ as o,o as a,c as t,a3 as n}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Link para referência de evento","description":"","frontmatter":{"title":"Link para referência de evento","id":"eproc-link-referencia-evento","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.0.7","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-link-referencia-evento.md","filePath":"funcionalidades/eproc-link-referencia-evento.md"}'),s={name:"funcionalidades/eproc-link-referencia-evento.md"};function r(i,e,d,c,l,m){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="link-para-referencia-de-evento" tabindex="-1">Link para referência de evento <a class="header-anchor" href="#link-para-referencia-de-evento" aria-label="Permalink to &quot;Link para referência de evento&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Transforma em links as menções a outros eventos (&quot;Refer. ao evento 12&quot;, &quot;Complementar ao evento 7&quot;, &quot;Status: FECHADO (17 - PETIÇÃO)&quot;). Um clique leva até o evento na tabela e o destaca. Nos documentos abertos a partir do processo, menções como &quot;evento 31, DEC1&quot; também viram links.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>:</p><ul><li>página do processo: eventos, lembretes e resumos de documentos;</li><li>documentos HTML abertos a partir do processo (minutas, decisões etc.);</li><li>documentos em PDF abertos a partir do processo, num painel no canto inferior esquerdo da janela.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Na página do processo, clique numa menção sublinhada a um evento. A tabela rola até o evento e o destaca. O botão Voltar do navegador retorna ao ponto anterior.</li><li>Num documento aberto a partir do processo, clique em &quot;evento 15&quot;, &quot;evento 31, DEC1&quot; ou &quot;eventos 3 e 5&quot;. A página do processo vem para a frente, no evento citado. Quando um documento específico é citado, ele também é aberto.</li><li>Em processos migrados do PJe, menções a IDs do PJe nos documentos (como &quot;Id. 10000000001&quot;) levam ao evento com aquele ID e abrem o documento correspondente. Um número escrito sem o &quot;Id.&quot; (como em &quot;Sentença, ID- 10000000001&quot;) também vira link, desde que coincida com o ID de um documento do processo.</li><li>Num documento em PDF, clique no botão &quot;N menções a eventos&quot;, no canto inferior esquerdo. O painel lista cada evento ou ID citado, com a página e o trecho em que aparece. Um clique faz o mesmo que os links dos documentos HTML.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Em documentos abertos a partir do processo, transformar menções a eventos em links que saltam até o evento na página do processo</td><td>ligada</td><td>Desligada, os links só aparecem na própria página do processo.</td></tr><tr><td>Em documentos PDF, mostrar um painel com as menções a eventos e IDs do PJe encontradas no texto</td><td>ligada</td><td>Desligada, os PDFs não mostram o painel. Só aparece com a opção acima ligada.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nos documentos, os links só funcionam enquanto a página do processo que os abriu continuar aberta. Se ela for fechada, os links voltam a ser texto comum.</li><li>Nos PDFs, o texto continua sem links: as menções ficam no painel. PDFs digitalizados (só imagem) não têm texto para ler e não mostram o painel. Só as primeiras 80 páginas são lidas.</li><li>Menções a eventos de outro processo citado ou a eventos que não existem na tabela não viram links.</li></ul><figure class="demo"><div class="demo__tela"><iframe src="/manual/demos/link-evento/reel.html" title="Demonstração animada" loading="lazy" tabindex="-1"></iframe></div><figcaption>Demonstração animada</figcaption></figure>',13)]))}const f=o(s,[["render",r]]);export{p as __pageData,f as default};
